package com.horabase.api.request;
import com.horabase.api.business.Business; import com.horabase.api.employee.Employee; import com.horabase.api.shift.Shift; import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="employee_requests") public class EmployeeRequest{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="business_id",nullable=false)private Business business;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="employee_id",nullable=false)private Employee employee;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="shift_id")private Shift shift;
 @Enumerated(EnumType.STRING)@Column(nullable=false,length=40)private EmployeeRequestType type;@Column(nullable=false,length=150)private String title;@Column(nullable=false,length=2000)private String description;@Column(name="related_date")private LocalDate relatedDate;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private EmployeeRequestStatus status=EmployeeRequestStatus.PENDING;@Column(name="admin_response",length=2000)private String adminResponse;@Column(name="resolved_at")private OffsetDateTime resolvedAt;@Column(name="created_at",nullable=false,updatable=false)private OffsetDateTime createdAt;@Column(name="updated_at",nullable=false)private OffsetDateTime updatedAt;
 @PrePersist void create(){createdAt=updatedAt=OffsetDateTime.now();}@PreUpdate void update(){updatedAt=OffsetDateTime.now();}
 public Long getId(){return id;}public Business getBusiness(){return business;}public void setBusiness(Business v){business=v;}public Employee getEmployee(){return employee;}public void setEmployee(Employee v){employee=v;}public Shift getShift(){return shift;}public void setShift(Shift v){shift=v;}public EmployeeRequestType getType(){return type;}public void setType(EmployeeRequestType v){type=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public LocalDate getRelatedDate(){return relatedDate;}public void setRelatedDate(LocalDate v){relatedDate=v;}public EmployeeRequestStatus getStatus(){return status;}public void setStatus(EmployeeRequestStatus v){status=v;}public String getAdminResponse(){return adminResponse;}public void setAdminResponse(String v){adminResponse=v;}public OffsetDateTime getResolvedAt(){return resolvedAt;}public void setResolvedAt(OffsetDateTime v){resolvedAt=v;}public OffsetDateTime getCreatedAt(){return createdAt;}public OffsetDateTime getUpdatedAt(){return updatedAt;}
}
